211	            if (amount == null || amount.signum() == 0) {
212	                return;
213	            }
214	            first.addOpening(person.getId(), amount);
215	            events.publishEvent(new OpeningSet(sheetId, user, person.getName(), first.getName(), amount));
216	        });
217	        periods.flush();
218	        events.publishEvent(new RolledOver(sheetId, user, fy, made.size()));
219	        return made;
220	    }
221	
222	    /**
223	     * Per person id, the due of their claims that count due by a date inside one of {@code within} and still OPEN or
224	     * PENDING at the end of {@code end}, by the status log, added up.
225	     */
226	    private Map<Long, BigDecimal> openAt(String sheetId, List<Period> within, LocalDate end) {
227	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
228	                .collect(Collectors.toMap(Person::getId, p -> p));
229	        RateTable table = rates.table(sheetId);
230	        Map<Long, BigDecimal> open = new HashMap<>();
231	        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
232	                .filter(c -> byId.containsKey(c.getPersonId()))
233	                .filter(c -> within.stream().anyMatch(p -> p.contains(c.getDueBy())))
234	                .filter(c -> c.getDeferredUntil() == null || !table.today().isBefore(c.getDeferredUntil()))
235	                .filter(c -> Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), end))
236	                .filter(c -> {
237	                    ClaimStatus then = Dues.statusAsOf(c, end);
238	                    return then == ClaimStatus.OPEN || then == ClaimStatus.PENDING;
239	                })
240	                .forEach(c -> {
241	                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
242	                    if (due != null) {
243	                        open.merge(c.getPersonId(), due, BigDecimal::add);
244	                    }
245	                });
246	        open.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
247	        return open;
248	    }
249	
250	    /**
251	     * Close a period, fixing each person's due-total and carried figure for it (see {@link #carried}), for every person on the sheet, and its own, their sum: the due figures of the claims due by a date inside it that counted (OPEN, PENDING and SETTLED,
252	     * but not an unbound OPEN claim dated within a hold of its person, nor a deferred one) at the end of its last day,
253	     * see {@link Dues#countsAsOf}, added up per person. A soft-closed period is closed with its figures fixed
254	     * afresh. Refused when it is already closed, or for a role the sheet's
255	     * permission matrix does not allow to close. Takes turns with claim changes on the
256	     * sheet, so the total fixed is the one the claims had at that moment.
257	     */
258	    @Transactional
259	    public Period close(String sheetId, String user, long periodId) {
260	        sheetRows.lockById(sheetId);
261	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
262	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
263	        if (!access.allows(sheetId, user, Permission.CLOSE)) {
264	            throw new PeriodRefused("Your role may not close a period on this sheet.");
265	        }
266	        if (period.isClosed()) {
267	            throw new PeriodRefused("The period is already closed.");
268	        }
269	        fix(sheetId, user, period, false, false);
270	        return period;
271	    }
272	
273	    /**
274	     * Soft-close an open period: its figures are fixed as a close fixes them, but claims due by a date inside it can
275	     * still be added, edited, opened, settled and voided. Refused when it is already closed or soft-closed, or
276	     * for a role the sheet's permission matrix does not allow to close.
277	     */
278	    @Transactional
279	    public Period softClose(String sheetId, String user, long periodId) {
280	        sheetRows.lockById(sheetId);
281	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
282	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
283	        if (!access.allows(sheetId, user, Permission.CLOSE)) {
284	            throw new PeriodRefused("Your role may not close a period on this sheet.");
285	        }
286	        if (period.isClosed()) {
287	            throw new PeriodRefused("The period is already closed.");
288	        }
289	        if (period.isSoftClosed()) {
290	            throw new PeriodRefused("The period is already soft-closed.");
291	        }
292	        fix(sheetId, user, period, false, true);
293	        return period;
294	    }
295	
296	    /**
297	     * When the sheet's today is changed and it has grace days, close every open period (neither closed nor
298	     * soft-closed) whose to-date plus the grace days is before the new today, in order of their to-dates, each as a close by hand would.
299	     */
300	    @EventListener
301	    @Transactional
302	    public void on(TodayChanged e) {
303	        Integer grace = sheets.graceDays(e.sheetId());
304	        if (grace == null) {
305	            return;
306	        }
307	        sheetRows.lockById(e.sheetId());
308	        list(e.sheetId()).stream()
309	                .filter(p -> !p.isFixed() && p.getToDate().plusDays(grace).isBefore(e.today()))
310	                .sorted(Comparator.comparing(Period::getToDate))
311	                .forEach(p -> fix(e.sheetId(), e.user(), p, true, false));
312	    }
313	
314	    /**
315	     * Each person's carried figure for the period, for every person on the sheet: the due figures as they stand of
316	     * their claims that count on the sheet's today (neither left out by a retirement nor deferred, see
317	     * {@link Dues#counts}) due by a date inside a period ending before it starts and still OPEN or PENDING at the end
318	     * of its last day, by the status log, added up per person, with the opening balances pasted for them in it.
319	     */
320	    private Map<Long, BigDecimal> carried(String sheetId, Period period, Map<Long, Person> byId, RateTable table) {
321	        List<Period> all = list(sheetId);
322	        Map<Long, BigDecimal> carried = new HashMap<>();
323	        byId.keySet().forEach(id -> carried.put(id, BigDecimal.ZERO.setScale(2)));
324	        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
325	                .filter(c -> byId.containsKey(c.getPersonId()))
326	                .filter(c -> all.stream().anyMatch(home -> home.contains(c.getDueBy())
327	                        && home.getToDate().isBefore(period.getFromDate())))
328	                .filter(c -> c.getDeferredUntil() == null || !table.today().isBefore(c.getDeferredUntil()))
329	                .filter(c -> Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), period.getToDate()))
330	                .filter(c -> {
331	                    ClaimStatus then = Dues.statusAsOf(c, period.getToDate());
332	                    return then == ClaimStatus.OPEN || then == ClaimStatus.PENDING;
333	                })
334	                .forEach(c -> {
335	                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
336	                    if (due != null) {
337	                        carried.merge(c.getPersonId(), due, BigDecimal::add);
338	                    }
339	                });
340	        period.getPersonOpenings().forEach((id, amount) -> {
341	            if (byId.containsKey(id)) {
342	                carried.merge(id, amount, BigDecimal::add);
343	            }
344	        });
345	        carried.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
346	        return carried;
347	    }
348	
349	    /**
350	     * Fix the period's due-totals and carried figures as of the end of its last day, and its pool members' cuts as
351	     * the pools stand now, and close it, or soft-close it.
352	     */
353	    private void fix(String sheetId, String user, Period period, boolean auto, boolean soft) {
354	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
355	                .collect(Collectors.toMap(Person::getId, p -> p));
356	        RateTable table = rates.table(sheetId);
357	        Map<Long, BigDecimal> totals = new HashMap<>();
358	        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
359	        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
360	                .filter(c -> period.contains(c.getDueBy())
361	                        && Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), period.getToDate()))
362	                .forEach(c -> {
363	                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
364	                    if (due != null) {
365	                        totals.merge(c.getPersonId(), due, BigDecimal::add);
366	                    }
367	                });
368	        totals.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
369	        period.close(totals, carried(sheetId, period, byId, table), soft);
370	        period.fixPoolCuts(pools.cuts(sheetId));
371	        BigDecimal total = period.getClosedTotal().setScale(2, RoundingMode.HALF_UP);
372	        periods.flush();
373	        events.publishEvent(new PeriodClosed(sheetId, user, period.getName(), total, auto, soft));
374	    }
375	
376	    /**
377	     * Reopen a closed or soft-closed period: its due-total, its people's carried figures and its pool cuts are live again, the current figures of the claims
378	     * due by a date inside it. Refused unless the sheet's permission matrix allows the user's role (a steward, unless
379	     * set), and when the period is neither closed nor soft-closed.
380	     */
381	    @Transactional
382	    public Period reopen(String sheetId, String user, long periodId) {
383	        sheetRows.lockById(sheetId);
384	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
385	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
386	        if (!access.allows(sheetId, user, Permission.REOPEN)) {
387	            throw new PeriodRefused("Your role may not reopen a period on this sheet.");
388	        }
389	        if (!period.isFixed()) {
390	            throw new PeriodRefused("The period is not closed.");
391	        }
392	        if (period.isLocked()) {
393	            throw new PeriodRefused("The period is locked.");
394	        }
395	        period.reopen();
396	        periods.flush();
397	        events.publishEvent(new PeriodReopened(sheetId, user, period.getName()));
398	        return period;
399	    }
400	
401	    /**
402	     * Lock a period, so it cannot be reopened, or unlock it. Refused unless the user is a steward, and when it is
403	     * already locked (or, to unlock, not locked).
404	     */
405	    @Transactional
406	    public Period lock(String sheetId, String user, long periodId, boolean lock) {
407	        sheetRows.lockById(sheetId);
408	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
409	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
410	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
411	            throw new PeriodRefused("Only a steward may " + (lock ? "lock" : "unlock") + " a period.");
412	        }
413	        if (period.isLocked() == lock) {
414	            throw new PeriodRefused(lock ? "The period is already locked." : "The period is not locked.");
415	        }
416	        period.setLocked(lock);
417	        periods.flush();
418	        events.publishEvent(lock ? new PeriodLocked(sheetId, user, period.getName())
419	                : new PeriodUnlocked(sheetId, user, period.getName()));
420	        return period;
421	    }
422	
423	    /** The closed period whose dates contain the date, if any. */
424	    @Transactional(readOnly = true)
425	    public Optional<Period> closedOn(String sheetId, LocalDate date) {
426	        return list(sheetId).stream().filter(p -> p.isClosed() && p.contains(date)).findFirst();
427	    }
428	
429	    /** The soft-closed period whose dates contain the date, if any. */
430	    @Transactional(readOnly = true)
431	    public Optional<Period> softClosedOn(String sheetId, LocalDate date) {
432	        return list(sheetId).stream().filter(p -> p.isSoftClosed() && p.contains(date)).findFirst();
433	    }
434	
435	    /**
436	     * Refuse a change to a claim due by any of the dates when a closed period contains it. Holds the
437	     * sheet's lock until the transaction ends, so a period cannot close while the change is made.
438	     */
439	    @Transactional
440	    public void requireOpen(String sheetId, LocalDate... dates) {
441	        sheetRows.lockById(sheetId);
442	        for (LocalDate date : dates) {
443	            closedOn(sheetId, date).ifPresent(p -> {
444	                throw new ClosedPeriodRefused(p.getName());
445	            });
446	        }
447	    }
448	}
